import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('basic lifecycle', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.equal((await h.start('a')).ok, false);
  assert.equal((await h.run('a'))!.status, 'queued');
  assert.equal((await h.taskStarted('a', 3)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  await h.taskStarted('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskEvicted('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskRequeued('a', 0);
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); }
  for (const t of [0, 1]) { await h.taskCompleted('a', t); }
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskCompleted('a', 2);
  assert.equal((await h.run('a'))!.status, 'completed');
  assert.equal((await h.cancel('a')).ok, false);
});

test('fail and cancel', async () => {
  const h = await createHost();
  await h.start('b');
  await h.taskStarted('b', 1);
  await h.taskFailed('b', 1);
  assert.equal((await h.run('b'))!.status, 'failed');
  assert.equal((await h.taskStarted('b', 0)).ok, false);
  await h.start('c');
  await h.taskStarted('c', 0);
  await h.taskCompleted('c', 0);
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.deepEqual(await h.run('c'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  await h.start('d');
  for (const t of [0, 1, 2]) { await h.taskStarted('d', t); await h.taskEvicted('d', t); }
  assert.equal((await h.run('d'))!.status, 'evicted');
});

